const yesterday = $now.minus({ days: 1 });
const targetDateStr = yesterday.toFormat('yyyy-MM-dd');

const metaAccessToken = $env.META_ACCESS_TOKEN || 'EAAG_DENTALPIN_META_ACCESS_TOKEN';
const igUserId = $env.META_IG_USER_ID || '17841400000000000';
const fbPageId = $env.META_FB_PAGE_ID || '100000000000000';
const dentalpinApiBase = ($env.DENTALPIN_API_BASE_URL || 'https://dental-api-2z19.onrender.com').replace(/\/+$/, '');
const dentalpinSyncPath = $env.DENTALPIN_SYNC_PATH || '/api/v1/social_automation/insights';
const dentalpinSyncUrl = `${dentalpinApiBase}${dentalpinSyncPath}`;
const dentalpinApiKey = $env.DENTALPIN_API_KEY || '';

return [
  {
    json: {
      target_date: targetDateStr,
      meta_access_token: metaAccessToken,
      ig_user_id: igUserId,
      fb_page_id: fbPageId,
      ig_account_id: 'dr_mokhtar_dental',
      fb_account_id: 'dr_mokhtar_cabinet',
      dentalpin_api_base: dentalpinApiBase,
      dentalpin_sync_url: dentalpinSyncUrl,
      dentalpin_api_key: dentalpinApiKey
    }
  }
];

const config = $('Init Config & Settings').first().json;
const mediaResponse = $json || {};
const mediaItems = Array.isArray(mediaResponse.data) ? mediaResponse.data : [];

// Trap 1: Handle new accounts with 0 media/reels or API errors gracefully
if (mediaItems.length === 0) {
  return [
    {
      json: {
        is_empty: true,
        target_date: config.target_date,
        dentalpin_api_base: config.dentalpin_api_base,
        dentalpin_sync_url: config.dentalpin_sync_url,
        dentalpin_api_key: config.dentalpin_api_key,
        ig_account_id: config.ig_account_id,
        meta_access_token: config.meta_access_token,
        id: null,
        media_type: null,
        metric_query: ''
      }
    }
  ];
}

// Trap 2: Meta Graph API throws error 100 if 'plays' is queried for static images/carousels.
// Dynamically tailor the metric query based on media_type:
return mediaItems.map(item => {
  const isVideo = item.media_type === 'VIDEO' || item.media_product_type === 'REELS';
  const metricQuery = isVideo ? 'saved,shares,plays,total_interactions' : 'saved,shares,total_interactions';

  return {
    json: {
      is_empty: false,
      id: item.id,
      caption: item.caption || '',
      media_type: item.media_type,
      media_product_type: item.media_product_type || 'POST',
      timestamp: item.timestamp,
      permalink: item.permalink,
      like_count: item.like_count || 0,
      comments_count: item.comments_count || 0,
      metric_query: metricQuery,
      meta_access_token: config.meta_access_token,
      target_date: config.target_date,
      dentalpin_api_base: config.dentalpin_api_base,
      dentalpin_sync_url: config.dentalpin_sync_url,
      dentalpin_api_key: config.dentalpin_api_key,
      ig_account_id: config.ig_account_id
    }
  };
});

const config = $('Init Config & Settings').first().json;
const mediaMetaItems = $('Filter Media & Set Adaptive Metrics').all();
const insightsResults = $('Fetch Media Insights').all();

let totalSaves = 0;
let totalShares = 0;
let totalPlays = 0;
let totalInteractions = 0;

const contentDetails = [];

for (let i = 0; i < mediaMetaItems.length; i++) {
  const meta = mediaMetaItems[i].json;
  if (meta.is_empty || !meta.id) continue;

  const insightItem = insightsResults[i]?.json || {};
  const dataArr = Array.isArray(insightItem.data) ? insightItem.data : [];

  function getVal(metricName) {
    const found = dataArr.find(d => d.name === metricName);
    return found?.values?.[0]?.value || 0;
  }

  const itemSaves = getVal('saved');
  const itemShares = getVal('shares');
  const itemPlays = getVal('plays');
  const itemInteractions = getVal('total_interactions') || (itemSaves + itemShares + (meta.like_count || 0) + (meta.comments_count || 0));

  totalSaves += itemSaves;
  totalShares += itemShares;
  totalPlays += itemPlays;
  totalInteractions += itemInteractions;

  contentDetails.push({
    id: meta.id,
    type: meta.media_product_type || meta.media_type,
    caption: (meta.caption || '').substring(0, 80),
    permalink: meta.permalink,
    timestamp: meta.timestamp,
    likes: meta.like_count,
    comments: meta.comments_count,
    saves: itemSaves,
    shares: itemShares,
    plays: itemPlays,
    interactions: itemInteractions
  });
}

// Sort top performing content by saves + interactions
contentDetails.sort((a, b) => (b.saves + b.interactions) - (a.saves + a.interactions));
const topContent = contentDetails.slice(0, 5);

const syncPayload = {
  platform: 'instagram',
  account_id: config.ig_account_id,
  date: config.target_date,
  saves: totalSaves
};

return [
  {
    json: {
      sync_payload: syncPayload,
      target_date: config.target_date,
      dentalpin_api_base: config.dentalpin_api_base,
      dentalpin_sync_url: config.dentalpin_sync_url,
      dentalpin_api_key: config.dentalpin_api_key,
      stats: {
        total_media_scanned: contentDetails.length,
        total_saves: totalSaves,
        total_shares: totalShares,
        total_plays: totalPlays,
        total_interactions: totalInteractions
      },
      top_content: topContent
    }
  }
];

const config = $('Init Config & Settings').first().json;

return [
  {
    json: {
      sync_payload: {
        platform: 'instagram',
        account_id: config.ig_account_id,
        date: config.target_date,
        saves: 0
      },
      target_date: config.target_date,
      dentalpin_api_base: config.dentalpin_api_base,
      dentalpin_sync_url: config.dentalpin_sync_url,
      dentalpin_api_key: config.dentalpin_api_key,
      stats: {
        total_media_scanned: 0,
        total_saves: 0,
        total_shares: 0,
        total_plays: 0,
        total_interactions: 0
      },
      top_content: [],
      message: 'New account with 0 media posts. Handled gracefully.'
    }
  }
];

const prev = $('Aggregate Content & Daily Saves').first()?.json || $('Handle Empty Media Gracefully').first().json;

return [
  {
    json: {
      success: true,
      execution_timestamp: $now.toISO(),
      target_date: prev.target_date,
      stats: prev.stats,
      top_content: prev.top_content,
      backend_status: $json,
      message: `Content performance & saves metric updated for ${prev.target_date}. Total Saves: ${prev.stats.total_saves}, Plays: ${prev.stats.total_plays}`
    }
  }
];
